+            // authorization. The real recipient must qualify its own publication.
+            let stamp = node
+                .sync_store(&node.identity.public())
+                .lock()
+                .expect("projection")
+                .history_sync_stamp(&channel)?;
+            let Some(stamp) = stamp else { return Ok(None) };
