        let alternate_addr = alternate.local_addr().unwrap();
        let query_sink = UdpSocket::bind("127.0.0.1:0").await.unwrap();
        let roster = Arc::new(Mutex::new(Roster::default()));
        roster.lock().unwrap().update(
