import { AnimatePresence, motion } from "framer-motion";
import { ease, useMotionOK } from "@/lib/motion";
import { useTranslation } from "react-i18next";
import { useTransfer } from "@/store/transfers";

/** A refined slim progress treatment for an in-flight file transfer keyed by
 *  `transferKey` (the per-file conv id for a save, or the optimistic message key for a
 *  send). Renders nothing when there is no active transfer for the key. Reads ONLY the
 *  transfers store, so its ~10/s updates don't re-render the surrounding message list. */
export function TransferBar({
  transferKey,
  waitingDirection,
  variant = "default",
  idleLabel,
}: {
  transferKey: string | undefined;
  waitingDirection?: "prepare" | "send";
  variant?: "default" | "compact" | "media";
  idleLabel?: string;
}) {
  const { t } = useTranslation();
  const tr = useTransfer(transferKey);
  const motionOK = useMotionOK();
  const active = !tr?.delivered && (!!tr || !!waitingDirection);
  const direction = tr?.direction ?? waitingDirection;
  const done = tr?.done ?? 0;
  const total = tr?.total ?? 0;
  const hasProgress =
    Number.isFinite(done) && Number.isFinite(total) && done >= 0 && total > 0;
  const pct = hasProgress
    ? Math.min(100, Math.floor((done / total) * 100))
    : undefined;
  const verb =
    direction === "prepare"
      ? t("transfer.preparing")
      : direction === "send"
        ? tr?.consent === "declined"
          ? t("transfer.recipientDeclined")
          : tr?.consent === "pending"
            ? t("transfer.awaitingApproval")
            : hasProgress && done >= total
              ? t("transfer.confirming")
              : tr?.done === 0
                ? t("transfer.awaitingRecipient")
                : t("transfer.sending")
        : t("transfer.saving");
  const eta =
    direction === "send" &&
    hasProgress &&
    done > 0 &&
    done < total &&
    tr?.etaSeconds != null &&
    Number.isFinite(tr.etaSeconds) &&
    tr.etaSeconds >= 0
      ? tr.etaSeconds < 60
        ? t("transfer.remainingSeconds", {
            seconds: Math.max(1, tr.etaSeconds),
          })
        : t("transfer.remainingMinutes", {
            minutes: Math.ceil(tr.etaSeconds / 60),
          })
      : null;
  if (!active && idleLabel)
    return (
      <span className="font-mono text-[11px] tabular-nums opacity-70">
        {idleLabel}
      </span>
    );
  const compact = variant !== "default";
  return (
    <AnimatePresence initial={false}>
      {active && (
        <motion.div
          key={transferKey}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          transition={{ duration: motionOK ? 0.12 : 0.08, ease }}
          className={
            variant === "media"
              ? "rounded-full border border-white/20 bg-background/90 px-3 py-2 text-foreground shadow-sm backdrop-blur-md"
              : compact
                ? "min-w-0 py-0.5"
                : "px-3 py-1.5"
          }
        >
          <div className="mb-1 flex flex-wrap items-center justify-between gap-x-3 gap-y-0.5 text-[11px]">
            <span
              title={verb}
              className={
                variant === "media"
                  ? "min-w-0 flex-1 truncate text-muted-foreground"
                  : "text-muted-foreground"
              }
            >
              {verb}
            </span>
            {compact && eta && (
              <span className="text-muted-foreground">{eta}</span>
            )}
            {pct !== undefined && (
              <span className="font-mono text-signal tabular-nums">{pct}%</span>
            )}
          </div>
          {eta && !compact && (
            <div className="mb-1 text-[11px] text-muted-foreground">{eta}</div>
          )}
          <span className="sr-only" role="status" aria-live="polite">
            {verb}
            {pct !== undefined ? ` ${Math.floor(pct / 10) * 10}%` : ""}
          </span>
          <div
            role="progressbar"
            aria-label={verb}
            aria-valuemin={0}
            aria-valuemax={100}
            aria-valuenow={pct}
            className={
              compact
                ? "h-0.5 w-full overflow-hidden rounded-full bg-muted"
                : "h-1 w-full overflow-hidden rounded-full bg-muted"
            }
          >
            <div
              className="transfer-progress h-full w-full origin-left rounded-full bg-signal"
              style={{
                transform: `scaleX(${hasProgress ? Math.min(1, done / total) : 0})`,
              }}
            />
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}
import { useTranslation } from "react-i18next";
import { Image, ImageOff } from "lucide-react";
import { humanSize } from "@/lib/format";
import type { FileStatus } from "@/lib/types";

export function ReceiveProgress({
  status,
  presentation = "file",
  size,
  preparing = false,
}: {
  status: FileStatus | undefined;
  presentation?: "file" | "image";
  size?: number;
  preparing?: boolean;
}) {
  const { t } = useTranslation();
  const total = status?.total ?? 0;
  const done = status?.done ?? 0;
  const hasProgress =
    Number.isFinite(done) && Number.isFinite(total) && done >= 0 && total > 0;
  const ratio = hasProgress ? Math.min(1, done / total) : 0;
  const percent = hasProgress ? Math.floor(ratio * 100) : undefined;
  const receiving = hasProgress && done > 0;

  if (presentation === "image") {
    const terminalKey = status?.unavailable
      ? "files.unavailable"
      : status?.consent === "pending"
        ? "files.approvalRequired"
        : status?.consent === "declined"
          ? "files.declined"
          : undefined;
    const imagePreparing = preparing || status?.ready || ratio === 1;
    const phase = t(
      terminalKey ??
        (imagePreparing
          ? "transfer.imagePreparing"
          : receiving
            ? "transfer.imageReceiving"
            : "transfer.imageWaiting"),
    );
    const transferring = !terminalKey && !imagePreparing;
    const showRing = transferring && receiving;
    const PhotoIcon =
      status?.unavailable || status?.consent === "declined" ? ImageOff : Image;
    return (
      <div className="flex min-w-0 max-w-full flex-col items-center gap-3 text-center text-card-foreground [overflow-wrap:anywhere]">
        <span className="sr-only" role="status" aria-live="polite">
          {phase}
        </span>
        <div
          role={transferring ? "progressbar" : undefined}
          aria-label={transferring ? phase : undefined}
          aria-valuemin={transferring ? 0 : undefined}
          aria-valuemax={transferring ? 100 : undefined}
          aria-valuenow={transferring ? percent : undefined}
          className="relative flex h-12 w-12 items-center justify-center"
        >
          {showRing && (
            <svg
              width="48"
              height="48"
              viewBox="0 0 48 48"
              fill="none"
              aria-hidden="true"
              className="absolute inset-0 -rotate-90"
            >
              <circle
                cx="24"
                cy="24"
                r="22.5"
                stroke="currentColor"
                strokeWidth="3"
                className="text-muted-foreground/25"
              />
              <circle
                cx="24"
                cy="24"
                r="22.5"
                pathLength="100"
                stroke="currentColor"
                strokeWidth="3"
                strokeLinecap="round"
                strokeDasharray="100"
                strokeDashoffset={100 - ratio * 100}
                className="text-signal transition-[stroke-dashoffset] duration-[160ms] ease-out motion-reduce:transition-none"
              />
            </svg>
          )}
          <PhotoIcon
            size={showRing ? 18 : 24}
            className="text-muted-foreground"
            aria-hidden="true"
          />
        </div>
        <div className="min-w-0 max-w-full space-y-1">
          <p className="text-xs font-medium tabular-nums">
            {showRing
              ? t("transfer.imageReceivingProgress", { percent })
              : phase}
          </p>
          <p className="text-[11px] text-muted-foreground">
            {size !== undefined && Number.isFinite(size) && size > 0
              ? t("transfer.imageDetails", { size: humanSize(size) })
              : t("transfer.image")}
          </p>
        </div>
      </div>
    );
  }

  if (status?.ready) return null;
  if (status?.unavailable)
    return (
      <div className="mt-2 text-[11px] opacity-75" role="status">
        {t("files.unavailable")}
      </div>
    );
  if (status?.consent === "pending" || status?.consent === "declined")
    return (
      <div className="mt-2 text-[11px] opacity-75" role="status">
        {t(
          status.consent === "pending"
            ? "files.approvalRequired"
            : "files.declined",
        )}
      </div>
    );
  return (
    <div
      className="mt-2"
      role="status"
      aria-label={
        receiving
          ? t("transfer.receivingProgress", { percent })
          : t("transfer.waiting")
      }
    >
      <div className="mb-1 flex items-center justify-between gap-3 text-[11px] opacity-75">
        <span>
          {receiving ? t("transfer.receiving") : t("transfer.waiting")}
        </span>
        {hasProgress && (
          <span className="font-mono tabular-nums">{percent}%</span>
        )}
      </div>
      <div
        role="progressbar"
        aria-label={t(receiving ? "transfer.receiving" : "transfer.waiting")}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={percent}
        className="h-1 w-full overflow-hidden rounded-full bg-current/15"
      >
        <div
          className="transfer-progress h-full origin-left bg-current"
          style={{ transform: `scaleX(${ratio})` }}
        />
      </div>
    </div>
  );
}

import { useCallback, useLayoutEffect, useRef, useState } from "react";
import { captureChatOwnership } from "@/store/chat";
import type { OutgoingMediaPreview } from "@/store/outgoingMediaPreviews";
import { useMotionOK } from "@/lib/motion";
import { useTranslation } from "react-i18next";
