beforeEach(() => { transfer.value = undefined; });
function render(m: Partial<ChatMessage>, readOnly = false) {
  return renderToStaticMarkup(createElement(MessageBubble, {
    m: { id: "queued", who: "me", text: "", wallClock: 1, fromMe: true, replyTo: null, ...m },
    parent: null, showAuthor: false, isChannel: false, readOnly, reactions: [], selfReactionId: "me", myName: "Me",
