  }));
}
const photo = { name: "photo.png", mime: "image/png", size: 8, fileConv: "file", media: true };
const sticker = { ...photo, name: encodeStickerMediaName("pack:test:wave", "👋", "png") };

it.each([photo, sticker])("keeps preparing media unobscured: $name", (file) => {
  const html = render({ id: null, clientId: "preparing", pending: true, metadataPending: true, file });
  expect(html).not.toContain("backdrop-blur-md");
  expect(html).not.toContain('role="progressbar"');
  expect(html).toContain("data-message-footer");
});
it.each([0, 4, 8])("keeps file byte ticks out of photo and sticker content (%s bytes)", (done) => {
  transfer.value = { fileConv: "file", direction: "send", done, total: 8 };
  for (const file of [photo, sticker]) {
    const html = render({ file });
