      void written
        .then(async () => {
          const png = await items[0].getType("image/png");
          const bitmap = await createImageBitmap(png);
          w.__mediaDiagnostic.copiedImage = [bitmap.width, bitmap.height];
          bitmap.close();
        })
        .catch((error) => {
          w.__mediaDiagnostic.copyError = String(error);
        });
      return written;
    };
